import { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAssetStore } from '../store/assetStore';
import { getAssetSummary, getFinancialAssets, getLandRecords, getConsents, refreshAssets, getAuditLog } from '../services/assets';
import { logout } from '../services/auth';
import CoreServices from '../components/CoreServices';

const CATEGORY_META: Record<string, { color: string; gradient: string; icon: string; bg: string }> = {
  DEPOSIT: { color: '#3b82f6', gradient: 'from-blue-500 to-blue-600', icon: 'account_balance', bg: 'bg-blue-50' },
  EQUITY: { color: '#10b981', gradient: 'from-emerald-500 to-emerald-600', icon: 'trending_up', bg: 'bg-emerald-50' },
  MUTUAL_FUND: { color: '#8b5cf6', gradient: 'from-violet-500 to-violet-600', icon: 'pie_chart', bg: 'bg-violet-50' },
  INSURANCE_POLICIES: { color: '#f59e0b', gradient: 'from-amber-500 to-amber-600', icon: 'shield', bg: 'bg-amber-50' },
  NPS: { color: '#14b8a6', gradient: 'from-teal-500 to-teal-600', icon: 'savings', bg: 'bg-teal-50' },
  GSTN: { color: '#ef4444', gradient: 'from-red-500 to-red-600', icon: 'receipt_long', bg: 'bg-red-50' },
};

export default function Dashboard() {
  const navigate = useNavigate();
  const {
    user, summary, assets, landRecords,
    setSummary, setAssets, setLandRecords, setConsents,
    isLoadingAssets, setLoadingAssets,
  } = useAssetStore();

  const [activeTab, setActiveTab] = useState<'overview' | 'land' | 'audit' | 'services'>('overview');
  const [refreshing, setRefreshing] = useState(false);
  const [animatedWorth, setAnimatedWorth] = useState(0);
  const [auditLogs, setAuditLogs] = useState<any[]>([]);

  const loadData = useCallback(async () => {
    setLoadingAssets(true);
    try {
      const [s, a, l, c] = await Promise.all([
        getAssetSummary(), getFinancialAssets(), getLandRecords(), getConsents(),
      ]);
      setSummary(s); setAssets(a); setLandRecords(l); setConsents(c);
      try { const audit = await getAuditLog(); setAuditLogs(audit.logs); } catch { /* ok */ }
    } catch (err) { console.error('Load failed', err); }
    finally { setLoadingAssets(false); }
  }, [setSummary, setAssets, setLandRecords, setConsents, setLoadingAssets]);

  useEffect(() => { loadData(); }, [loadData]);

  useEffect(() => {
    if (!summary) return;
    const target = summary.totalWithLand || summary.totalNetWorth;
    const dur = 1800, start = performance.now();
    const anim = (now: number) => {
      const p = Math.min((now - start) / dur, 1);
      setAnimatedWorth(Math.round(target * (1 - Math.pow(1 - p, 4))));
      if (p < 1) requestAnimationFrame(anim);
    };
    requestAnimationFrame(anim);
  }, [summary]);

  async function handleRefresh() {
    setRefreshing(true);
    try { await refreshAssets(); await loadData(); } catch { }
    finally { setRefreshing(false); }
  }

  async function handleLogout() {
    try { await logout(); } catch { }
    useAssetStore.getState().logout();
    navigate('/');
  }

  function fmt(n: number) {
    if (n >= 10000000) return `${(n / 10000000).toFixed(2)}Cr`;
    if (n >= 100000) return `${(n / 100000).toFixed(2)}L`;
    return `${n.toLocaleString('en-IN')}`;
  }

  const tabs = [
    { key: 'overview' as const, label: 'Overview', icon: 'grid_view' },
    { key: 'land' as const, label: `Property`, icon: 'apartment' },
    { key: 'audit' as const, label: 'Activity', icon: 'monitoring' },
    { key: 'services' as const, label: 'Services', icon: 'apps' },
  ];

  const initials = (user?.name || 'U').split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);

  // Fallback for mock visuals
  const mockBars = [40, 65, 30, 80, 50, 95, 60, 45, 85, 55, 75, 40];

  return (
    <div className="min-h-screen bg-[#f3f4f8] text-[#111827] font-sans selection:bg-black selection:text-white pb-20">

      {/* Floating Pill Navigation */}
      <nav className="fixed top-6 inset-x-0 mx-auto max-w-[1500px] px-6 z-50 pointer-events-none flex items-center justify-between">
        {/* Logo area */}
        <div className="pointer-events-auto flex items-center gap-3">
          <div className="w-10 h-10 bg-black text-white rounded-full flex items-center justify-center shadow-lg">
            <span className="material-symbols-outlined text-[20px]" style={{ fontVariationSettings: "'FILL' 1" }}>account_balance</span>
          </div>
        </div>

        {/* Center Pill Tabs */}
        <div className="pointer-events-auto flex items-center bg-white/90 backdrop-blur-md rounded-full shadow-sm p-1.5 gap-1 border border-black/[0.04]">
          {tabs.map(t => (
            <button
              key={t.key}
              onClick={() => setActiveTab(t.key)}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-full text-[13px] font-semibold transition-all duration-300 ${
                activeTab === t.key
                  ? 'bg-black text-white shadow-md'
                  : 'text-gray-500 hover:text-black hover:bg-gray-100'
              }`}
            >
              <span className="material-symbols-outlined text-[18px]" style={{ fontVariationSettings: activeTab === t.key ? "'FILL' 1" : "'FILL' 0" }}>{t.icon}</span>
              {t.label}
            </button>
          ))}
        </div>

        {/* Right Tools */}
        <div className="pointer-events-auto flex items-center gap-3 bg-white/90 backdrop-blur-md rounded-full p-1.5 border border-black/[0.04] shadow-sm">
          <button onClick={handleRefresh} disabled={refreshing} className="w-10 h-10 flex items-center justify-center rounded-full bg-gray-100 text-black hover:bg-gray-200 transition-colors disabled:opacity-50">
            {refreshing ? <div className="w-4 h-4 border-2 border-black/20 border-t-black rounded-full animate-spin" /> : <span className="material-symbols-outlined text-[18px]">sync</span>}
          </button>
          <div className="flex items-center gap-2 pl-2 pr-1">
            <div className="w-8 h-8 rounded-full bg-black text-white flex items-center justify-center text-[11px] font-bold tracking-wide">
              {initials}
            </div>
          </div>
          <button onClick={handleLogout} className="w-10 h-10 flex items-center justify-center rounded-full hover:bg-red-50 text-gray-400 hover:text-red-500 transition-colors">
            <span className="material-symbols-outlined text-[18px]">logout</span>
          </button>
        </div>
      </nav>

      {/* Main Content Area */}
      <main className="max-w-[1500px] mx-auto px-6 pt-32 space-y-8">

        {/* Header */}
        <div className="flex items-center gap-4">
          <h1 className="text-[44px] font-medium tracking-tight text-gray-900 leading-none">Asset Portfolio Performance</h1>
          <div className="flex items-center gap-2 ml-auto">
            <button className="flex items-center justify-center w-10 h-10 rounded-full bg-white shadow-sm border border-black/[0.04] text-gray-500 hover:text-black hover:bg-gray-50 transition-colors"><span className="material-symbols-outlined text-[18px]">search</span></button>
            <button className="flex items-center justify-center w-10 h-10 rounded-full bg-black text-white shadow-sm"><span className="material-symbols-outlined text-[18px]">add</span></button>
          </div>
        </div>

        {/* Overview Tab Content */}
        {activeTab === 'overview' && (
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 animate-[fade-in_0.4s_ease-out]">

            {/* HERO / ASSISTANT WIDGET (Left Column) */}
            <div className="lg:col-span-4 bg-[#e2f0e7] rounded-[32px] p-8 relative overflow-hidden flex flex-col justify-between min-h-[480px] shadow-sm">
              <div className="flex items-center justify-between z-10 relative">
                <span className="text-[15px] font-medium text-gray-800">Portfolio AI summary</span>
                <button className="w-8 h-8 bg-white/50 rounded-full flex items-center justify-center hover:bg-white text-gray-700 transition-colors">
                  <span className="material-symbols-outlined text-[16px]">close</span>
                </button>
              </div>

              {/* Abstract mesh / organic shape simulation using blurred circles */}
              <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-64 h-64 bg-gradient-to-tr from-rose-300 to-amber-200 rounded-full blur-3xl opacity-60 animate-[pulse_6s_ease-in-out_infinite]" />
              <div className="absolute top-1/3 left-1/3 w-48 h-48 bg-gradient-to-br from-teal-300 to-emerald-300 rounded-full blur-2xl opacity-50 mix-blend-multiply" />

              <div className="z-10 relative mt-auto">
                <div className="bg-[#d1e8d9]/80 backdrop-blur-md rounded-2xl p-5 border border-white/20">
                  <div className="flex items-start gap-4">
                    <p className="text-[13px] text-gray-800 leading-relaxed font-medium">
                      Your total net worth grew steadily. Compare financial vs physical assets and analyze distributions across various categories.
                    </p>
                    <button className="w-10 h-10 shrink-0 bg-black text-white rounded-full flex items-center justify-center hover:scale-105 transition-transform shadow-md">
                      <span className="material-symbols-outlined text-[18px]">arrow_forward</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>

            {/* RIGHT COLUMN METRICS */}
            <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-6">

              {/* Total Financial Assets Widget */}
              <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100 flex flex-col">
                <div className="flex justify-between items-start mb-6">
                  <div className="flex items-center gap-2 text-gray-500">
                    <span className="material-symbols-outlined text-[18px]">account_balance</span>
                    <span className="text-[14px] font-medium">Financial Assets</span>
                  </div>
                  <div className="flex gap-2">
                    <button className="w-8 h-8 bg-gray-50 rounded-full flex items-center justify-center text-gray-400 hover:text-black transition-colors"><span className="material-symbols-outlined text-[16px]">more_horiz</span></button>
                  </div>
                </div>

                <p className="text-[11px] text-gray-400 font-medium uppercase tracking-wider mb-1">Total Value</p>
                <div className="flex items-baseline gap-2 mb-8">
                  <span className="text-[42px] font-medium tracking-tight leading-none">₹{summary ? fmt(summary.totalNetWorth).replace('₹', '') : '0'}</span>
                </div>

                {/* Simulated Bar Chart */}
                <div className="mt-auto h-32 flex items-end justify-between gap-2 px-2 relative">
                  <div className="absolute top-1/3 left-0 right-0 border-t border-dashed border-gray-200" />
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2 bg-[#eaf491] text-[#717b1d] text-[10px] font-bold px-2 py-1 rounded-full shadow-sm z-10 hidden sm:block">
                    ₹{summary ? fmt(summary.totalNetWorth).replace('₹', '') : '0'}
                  </div>

                  {mockBars.map((height, i) => (
                    <div key={i} className="w-full bg-gray-100 rounded-t-full relative group h-full flex items-end">
                      <div 
                        className={`w-full rounded-t-full transition-all duration-1000 ${i === 6 ? 'bg-gradient-to-t from-gray-200 to-gray-400 striped-bg' : 'bg-gray-200 group-hover:bg-gray-300'}`} 
                        style={{ height: `${height}%` }} 
                      />
                    </div>
                  ))}
                </div>
                <div className="flex justify-between text-[10px] text-gray-400 font-medium mt-3 px-2">
                  <span>Feb</span><span>Mar</span><span>Apr</span><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span>
                </div>
              </div>

              {/* Property / Land Assets Widget */}
              <div className="bg-[#eff2fc] rounded-[32px] p-8 shadow-sm border border-blue-50/50 flex flex-col relative overflow-hidden">
                <div className="flex justify-between items-start mb-6 z-10 relative">
                  <div className="flex items-center gap-2 text-gray-600">
                    <span className="material-symbols-outlined text-[18px]">apartment</span>
                    <span className="text-[14px] font-medium">Property Value</span>
                  </div>
                  <div className="flex bg-white/60 backdrop-blur-sm rounded-full p-1 gap-1">
                    <button className="w-7 h-7 rounded-full bg-black text-white flex items-center justify-center"><span className="material-symbols-outlined text-[14px]">pie_chart</span></button>
                    <button className="w-7 h-7 rounded-full text-gray-500 hover:bg-white flex items-center justify-center"><span className="material-symbols-outlined text-[14px]">show_chart</span></button>
                  </div>
                </div>

                <p className="text-[11px] text-gray-500 font-medium uppercase tracking-wider mb-1 z-10 relative">Estimated</p>
                <div className="flex items-baseline gap-2 mb-8 z-10 relative">
                  <span className="text-[42px] font-medium tracking-tight text-[#1b1464] leading-none">
                    ₹{summary ? fmt(summary.estimatedLandValue || 0).replace('₹', '') : '0'}
                  </span>
                </div>

                {/* Abstract Line Chart Simulation */}
                <div className="absolute bottom-0 left-0 right-0 h-40 opacity-40 pointer-events-none">
                  <svg viewBox="0 0 400 100" preserveAspectRatio="none" className="w-full h-full">
                    <path d="M0,80 C50,90 100,50 150,60 C200,70 250,30 300,40 C350,50 400,10 400,10 L400,100 L0,100 Z" fill="url(#blue-grad)" />
                    <path d="M0,80 C50,90 100,50 150,60 C200,70 250,30 300,40 C350,50 400,10 400,10" fill="none" stroke="#4338ca" strokeWidth="2" strokeDasharray="6,4" />
                    <defs>
                      <linearGradient id="blue-grad" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#4338ca" stopOpacity="0.4" />
                        <stop offset="100%" stopColor="#4338ca" stopOpacity="0" />
                      </linearGradient>
                    </defs>
                  </svg>
                  <div className="absolute top-1/2 left-2/3 -translate-x-1/2 bg-[#dcfce7] text-teal-800 text-[10px] font-bold px-2 py-1 rounded-full shadow-sm">
                    +5%
                  </div>
                </div>
              </div>

              {/* Category Summary Widget */}
              <div className="bg-[#e9eee9] rounded-[32px] p-8 shadow-sm flex flex-col">
                <div className="flex justify-between items-start mb-6">
                  <div className="flex items-center gap-2 text-gray-700">
                    <span className="material-symbols-outlined text-[18px]">category</span>
                    <span className="text-[14px] font-medium">Asset Summary</span>
                  </div>
                  <button className="w-8 h-8 bg-white/60 rounded-full flex items-center justify-center text-gray-500 hover:text-black transition-colors"><span className="material-symbols-outlined text-[16px]">open_in_new</span></button>
                </div>

                <div className="flex gap-4 h-48 items-end mt-auto">
                  {/* Fake bars for composition */}
                  <div className="flex-1 flex flex-col gap-2 relative">
                    <span className="text-[11px] text-gray-500 font-medium">Deposits</span>
                    <div className="w-full bg-[#dcfce7] rounded-xl p-4 flex flex-col justify-between" style={{ height: '80%' }}>
                      <span className="text-[14px] font-bold text-gray-800">40%</span>
                      <span className="text-[10px] text-gray-500">Growth 3%</span>
                    </div>
                  </div>
                  <div className="flex-1 flex flex-col gap-2 relative">
                    <span className="text-[11px] text-gray-500 font-medium">Equities</span>
                    <div className="w-full bg-[#eaf491] rounded-xl p-4 flex flex-col justify-between" style={{ height: '60%' }}>
                      <span className="text-[14px] font-bold text-gray-800">35%</span>
                      <span className="text-[10px] text-gray-500">Growth 8%</span>
                    </div>
                  </div>
                  <div className="flex-1 flex flex-col gap-2 relative">
                    <span className="text-[11px] text-gray-500 font-medium">Other</span>
                    <div className="w-full bg-white rounded-xl p-4 flex flex-col justify-between" style={{ height: '40%' }}>
                      <span className="text-[14px] font-bold text-gray-800">25%</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Doughnut / Asset List Widget */}
              <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100 flex flex-col">
                 <div className="flex justify-between items-start mb-6">
                  <div className="flex items-center gap-2 text-gray-600">
                    <span className="material-symbols-outlined text-[18px]">pie_chart</span>
                    <span className="text-[14px] font-medium">Distribution</span>
                  </div>
                  <div className="flex gap-2">
                    <button className="w-8 h-8 bg-gray-50 rounded-full flex items-center justify-center text-gray-400"><span className="material-symbols-outlined text-[16px]">more_horiz</span></button>
                  </div>
                </div>

                <div className="flex-1 flex items-center justify-center relative">
                  {/* CSS Doughnut simulation */}
                  <div className="w-40 h-40 rounded-full border-[24px] border-gray-50 relative flex items-center justify-center">
                    <div className="absolute inset-[-24px] rounded-full border-[24px] border-transparent border-t-[#dcfce7] border-r-[#eaf491] border-b-[#eff2fc] border-l-[#fce7f3] rotate-45 opacity-80" />
                    <div className="text-center">
                      <span className="block text-[22px] font-bold text-gray-800 leading-none">{summary?.categoryBreakdown.length || 0}</span>
                      <span className="text-[10px] text-gray-400">Categories</span>
                    </div>
                  </div>
                </div>

                <div className="flex flex-wrap gap-3 mt-6 justify-center">
                  {summary?.categoryBreakdown.slice(0, 4).map(cat => (
                    <div key={cat.fiType} className="flex items-center gap-1.5">
                      <span className="w-2 h-2 rounded-full" style={{ backgroundColor: CATEGORY_META[cat.fiType]?.color || '#ccc' }} />
                      <span className="text-[11px] text-gray-500 font-medium">{cat.label}</span>
                    </div>
                  ))}
                </div>
              </div>

            </div>
          </div>
        )}

        {/* Other Tabs (Simplified fallback for now, maintaining functional state) */}
        {activeTab === 'land' && (
          <div className="animate-[fade-in_0.3s_ease]">
            {landRecords.length > 0 ? (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {landRecords.map(r => (
                  <div key={r.id} className="bg-white rounded-[32px] p-6 shadow-sm border border-gray-100">
                    <div className="w-12 h-12 bg-[#eff2fc] rounded-2xl flex items-center justify-center mb-4">
                      <span className="material-symbols-outlined text-indigo-600">terrain</span>
                    </div>
                    <p className="font-bold text-[16px] text-gray-900">{r.surveyNumber}</p>
                    <p className="text-[13px] text-gray-500">{r.district}, {r.state}</p>
                    <div className="mt-4 pt-4 border-t border-gray-100 flex justify-between">
                      <span className="text-[12px] text-gray-400">Area</span>
                      <span className="text-[13px] font-bold">{r.areaSqft} sqft</span>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="bg-white rounded-[32px] p-16 text-center shadow-sm border border-gray-100">
                <span className="material-symbols-outlined text-[48px] text-gray-300 mb-4">landscape</span>
                <p className="text-gray-500">No property records found.</p>
              </div>
            )}
          </div>
        )}

        {activeTab === 'audit' && (
          <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100">
             <h3 className="text-[18px] font-bold mb-6">Activity History</h3>
             {auditLogs.length > 0 ? (
               <div className="space-y-4">
                 {auditLogs.map(log => (
                   <div key={log.id} className="flex items-start gap-4 p-4 rounded-2xl bg-gray-50/50">
                     <span className="material-symbols-outlined text-gray-400">history</span>
                     <div>
                       <p className="text-[13px] font-bold">{log.action.replace(/_/g, ' ')}</p>
                       <p className="text-[11px] text-gray-500">{new Date(log.timestamp).toLocaleString()}</p>
                     </div>
                   </div>
                 ))}
               </div>
             ) : <p className="text-gray-500 text-sm">No activity recorded.</p>}
          </div>
        )}

        {activeTab === 'services' && (
          <div className="bg-white rounded-[32px] p-8 shadow-sm border border-gray-100">
            <CoreServices />
          </div>
        )}

      </main>

      {/* Striped background utility for charts */}
      <style>{`
        .striped-bg {
          background-image: repeating-linear-gradient(
            45deg,
            rgba(0,0,0,0.03) 0px,
            rgba(0,0,0,0.03) 4px,
            transparent 4px,
            transparent 8px
          );
        }
      `}</style>
    </div>
  );
}

