const FI_COLORS: Record<string, { iconBg: string; tag: string }> = {
  DEPOSIT:            { iconBg: 'bg-zinc-900 text-lime-300', tag: 'Primary' },
  EQUITY:             { iconBg: 'bg-lime-100 text-lime-800', tag: 'Equity' },
  MUTUAL_FUND:        { iconBg: 'bg-lime-100 text-lime-800', tag: 'MF' },
  INSURANCE_POLICIES: { iconBg: 'bg-zinc-100 text-zinc-700', tag: 'Insurance' },
  NPS:                { iconBg: 'bg-teal-100 text-teal-800', tag: 'NPS' },
  GSTN:               { iconBg: 'bg-red-100 text-red-800',   tag: 'GSTN' },
};

const INSTITUTION_META: Record<string, { bg: string; text: string; abbr: string; gradient: string }> = {
  // Banks
  'HDFC Bank': { bg: 'bg-blue-900', text: 'text-white', abbr: 'HDFC', gradient: 'from-blue-900 to-blue-800' },
  'State Bank of India': { bg: 'bg-sky-600', text: 'text-white', abbr: 'SBI', gradient: 'from-sky-600 to-sky-500' },
  'ICICI Bank': { bg: 'bg-orange-600', text: 'text-white', abbr: 'ICICI', gradient: 'from-orange-600 to-orange-500' },
  'Axis Bank': { bg: 'bg-rose-900', text: 'text-white', abbr: 'AXIS', gradient: 'from-rose-900 to-rose-800' },
  'Kotak Mahindra': { bg: 'bg-red-600', text: 'text-white', abbr: 'KOTAK', gradient: 'from-red-600 to-red-500' },

  // Brokers
  'Zerodha Broking': { bg: 'bg-blue-500', text: 'text-white', abbr: 'ZER', gradient: 'from-blue-500 to-blue-400' },
  'Upstox': { bg: 'bg-purple-600', text: 'text-white', abbr: 'UPST', gradient: 'from-purple-600 to-purple-500' },
