function getBankBrandColors(name: string) {
  const n = (name || '').toLowerCase();
  if (n.includes('hdfc')) return 'bg-[#004b87] text-white';
  if (n.includes('sbi') || n.includes('state bank')) return 'bg-[#007cc3] text-white';
  if (n.includes('icici')) return 'bg-[#f15a22] text-white';
  if (n.includes('axis')) return 'bg-[#97144d] text-white';
  if (n.includes('kotak')) return 'bg-[#ed1c24] text-white';
  if (n.includes('yes')) return 'bg-[#00529b] text-white';
  if (n.includes('indusind')) return 'bg-[#802a2a] text-white';
  if (n.includes('pnb') || n.includes('punjab')) return 'bg-[#fbb034] text-black';
  return null;
}

function AssetCard({ asset, fmt }: { asset: any; fmt: (n: number) => string }) {
  const colors = FI_COLORS[asset.fiType] || FI_COLORS.DEPOSIT;
  const icon = FI_ICONS[asset.fiType] || <Wallet className="size-4" strokeWidth={1.75} />;

  const isBank = asset.fiType === 'DEPOSIT';
  const brandBg = isBank ? getBankBrandColors(asset.institutionName) : null;
  const iconContainerClass = brandBg ? brandBg : colors.iconBg;

  return (
    <article className="bg-white rounded-2xl p-4 shadow-sm hover:shadow-md transition">
      <div className="flex items-start justify-between mb-4">
        <div className={`size-10 rounded-xl ${iconContainerClass} grid place-items-center shadow-sm`}>{icon}</div>
        <span className="text-[10px] font-medium bg-zinc-100 text-zinc-600 rounded-full px-2 py-0.5">{colors.tag}</span>
      </div>

