              <div className="w-full h-[1px] bg-[#8c6b12]/50 absolute bottom-2 left-0"></div>
              <div className="w-[1px] h-full bg-[#8c6b12]/50 absolute left-2.5 top-0"></div>
              <div className="w-[1px] h-full bg-[#8c6b12]/50 absolute right-2.5 top-0"></div>
              <div className="w-3 h-full bg-[#8c6b12]/20 absolute left-1/2 -translate-x-1/2 top-0 border-x border-[#8c6b12]/40"></div>
            </div>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" className="text-[#98cc3b] rotate-90 ml-1">
              <path d="M5 12a10 10 0 0 1 14 0" />
              <path d="M8 12a6 6 0 0 1 8 0" />
              <path d="M11 12a2 2 0 0 1 2 0" />
            </svg>
          </div>
          <div className="relative z-10 flex items-center gap-4 mt-5 text-white">
            <span className="text-[14px] leading-none tracking-[0.2em] mb-1">••••</span>
            <span className="text-[14px] leading-none tracking-[0.2em] mb-1">••••</span>
            <span className="text-[14px] leading-none tracking-[0.2em] mb-1">••••</span>
            <span className="font-mono text-[17px] tracking-[0.15em] leading-none">{last4}</span>
          </div>
          <div className="relative z-10 flex justify-between items-end mt-4">
            <div className="flex gap-10">
              <div>
                <p className="text-[7px] tracking-widest text-zinc-400 uppercase mb-0.5">Cardholder</p>
                <p className="text-[11px] font-semibold tracking-widest uppercase text-white/90">ASSETMAP USER</p>
              </div>
              <div>
                <p className="text-[7px] tracking-widest text-zinc-400 uppercase mb-0.5">Exp</p>
                <p className="text-[11px] font-bold tracking-wider text-white/90">08/29</p>
              </div>
            </div>
            <div className="text-2xl font-bold italic pr-1 tracking-tighter text-white/90 select-none">VISA</div>
          </div>
        </div>
        <div className="px-3 pt-3 pb-2 flex justify-between items-end">
           <div>
             <p className="text-xs text-zinc-500 mb-0.5">Checking <span className="tracking-widest ml-1">••{last4}</span></p>
             <p className="text-[22px] font-display font-semibold text-zinc-800">{fmt(asset.balance)}</p>
           </div>
           <div className="text-right">
             <div className="flex justify-end gap-0.5 mb-1">
                <span className="size-[6px] rounded-full bg-cyan-400" />
                <span className="size-[6px] rounded-full bg-emerald-400" />
                <span className="size-[6px] rounded-full bg-amber-400" />
             </div>
             <p className="text-[11px] text-emerald-600 font-medium">Active</p>
           </div>
        </div>
      </article>
    );
  }

  if (asset.fiType === 'INSURANCE_POLICIES') {
    return <InsuranceCard policy={asset} fmt={fmt} density={density} />;
  }

  if (asset.fiType === 'MUTUAL_FUND') {
    return <MutualFundCard fund={asset} fmt={fmt} density={density} />;
  }

  if (asset.fiType === 'EQUITY') {
    return <StockCard stock={asset} fmt={fmt} density={density} />;
  }

  // Fallback
  const colors = FI_COLORS[asset.fiType] || FI_COLORS.DEPOSIT;
  const icon = FI_ICONS[asset.fiType] || <Wallet className="size-4" strokeWidth={1.75} />;
  return (
    <article className="bg-white rounded-2xl p-4 shadow-sm hover:shadow-md transition border border-zinc-100">
      <div className="flex items-start justify-between mb-4">
        <div className={\`size-10 rounded-xl \${colors.iconBg} grid place-items-center\`}>{icon}</div>
        <span className="text-[10px] font-medium bg-zinc-100 text-zinc-600 rounded-full px-2 py-0.5">{colors.tag}</span>
      </div>
      <p className="text-xs text-zinc-500 mb-1 font-mono">{asset.accountRef}</p>
      <h3 className="text-base font-display font-semibold leading-tight">{asset.institutionName}</h3>
      <p className="mt-3 text-2xl font-display font-bold">{fmt(asset.balance)}</p>
    </article>
  );
}

function InsuranceCard({ policy, fmt, density }: { policy: any; fmt: (n:number)=>string; density: Density }) {
  const cardPad = density === "compact" ? "p-3" : "p-4";
  return (
    <article className={\`bg-white rounded-2xl \${cardPad} shadow-sm border border-zinc-100 hover:shadow-md transition flex flex-col\`}>
      <div className="flex items-start justify-between mb-3">
        <div className="size-10 rounded-xl bg-zinc-100 grid place-items-center">
          <Shield className="size-4 text-zinc-700" strokeWidth={1.75} />
        </div>
        <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-sky-100 text-sky-700">
          Active
        </span>
      </div>
      <h3 className="text-sm font-display leading-tight">{policy.institutionName}</h3>
      <p className="text-xs text-zinc-500 mt-1">{policy.accountRef}</p>
      <div className="mt-auto pt-4 flex items-baseline justify-between">
        <span className="text-[10px] font-medium uppercase tracking-widest text-zinc-400">Sum Assured</span>
        <span className="text-sm font-semibold text-zinc-900">{fmt(policy.balance)}</span>
      </div>
    </article>
  );
}

function MutualFundCard({ fund, fmt, density }: { fund: any; fmt: (n:number)=>string; density: Density }) {
  const cardPad = density === "compact" ? "p-3" : "p-4";
  return (
    <article className={\`bg-white rounded-2xl \${cardPad} shadow-sm border border-zinc-100 hover:shadow-md transition\`}>
      <div className="flex items-start justify-between mb-3">
        <div className="size-10 rounded-xl bg-lime-100 text-lime-800 grid place-items-center">
          <PieChart className="size-4" strokeWidth={1.75} />
        </div>
        <button className="size-7 rounded-full bg-zinc-100 grid place-items-center text-zinc-500 hover:bg-zinc-900 hover:text-white transition">
          <ArrowUpRight className="size-3.5" strokeWidth={2} />
        </button>
      </div>
      <h3 className="text-base font-display leading-tight line-clamp-1">{fund.institutionName}</h3>
      <p className="text-xs text-zinc-500 mt-1">{fund.accountRef}</p>

      <div className="mt-4 flex items-baseline gap-2">
        <span className="text-xl font-display">{fmt(fund.balance)}</span>
        <span className="text-xs font-medium text-emerald-600">+4.2%</span>
      </div>
    </article>
  );
}

function StockCard({ stock, fmt, density }: { stock: any; fmt: (n:number)=>string; density: Density }) {
  const cardPad = density === "compact" ? "p-3" : "p-4";
  return (
    <article className={\`bg-white rounded-2xl \${cardPad} shadow-sm border border-zinc-100 hover:shadow-md transition\`}>
      <div className="flex items-start justify-between mb-3">
        <div>
          <h3 className="text-base font-display leading-none">{stock.institutionName}</h3>
          <p className="text-xs text-zinc-500 mt-1">{stock.accountRef}</p>
        </div>
        <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-lime-300 text-zinc-900">
          +1.8%
        </span>
      </div>
      <p className="text-xl font-display">{fmt(stock.balance)}</p>
      <div className="mt-2 h-10 bg-zinc-50 rounded animate-pulse"></div>
    </article>
  );
}


function ProfileMenu({ user, onLogout }: { user: any; onLogout: () => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const onClick = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  return (
    <div ref={ref} className="relative z-50">
      <button onClick={() => setOpen((v) => !v)} className="flex items-center gap-2 bg-white rounded-full pl-1 pr-3 py-1 shadow-sm border border-zinc-200 hover:bg-zinc-100 active:scale-[0.98] transition">
        <div className="size-8 rounded-full bg-lime-300 text-zinc-900 font-bold grid place-items-center">
           {user?.name?.[0] || 'U'}
        </div>
        <span className="hidden sm:flex flex-col items-start leading-tight">
          <span className="text-xs font-semibold">{user?.name || 'User'}</span>
          <span className="text-[10px] text-zinc-500">{user?.mobile || 'Client'}</span>
        </span>
        <ChevronDown className={"size-3.5 text-zinc-500 transition " + (open ? "rotate-180" : "")} strokeWidth={2} />
      </button>

      {open && (
        <div className="absolute right-0 mt-2 w-60 bg-white rounded-2xl shadow-lg ring-1 ring-black/5 py-2 z-50 origin-top-right">
          <div className="px-4 py-3 border-b border-zinc-100">
            <p className="text-sm font-semibold">{user?.name}</p>
            <p className="text-xs text-zinc-500">{user?.mobile}</p>
          </div>
          <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-left hover:bg-zinc-50 transition text-zinc-800"><Settings className="size-4 text-zinc-500" /> Account Settings</button>
          <div className="my-1 border-t border-zinc-100" />
          <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-2 text-sm text-left hover:bg-zinc-50 transition text-rose-600"><LogOut className="size-4 text-rose-500" /> Sign out</button>
        </div>
      )}
    </div>
  );
}

function RailIcon({ children, active, label, onClick }: { children: React.ReactNode; active?: boolean; label?: string; onClick?: ()=>void }) {
  return (
    <button onClick={onClick} title={label} className={"size-10 rounded-full grid place-items-center transition active:scale-95 " + (active ? "bg-zinc-900 text-white shadow-md" : "bg-white/60 text-zinc-500 hover:bg-white hover:text-zinc-900 hover:shadow-sm")}>
      {children}
    </button>
  );
}

function Kpi({ label, value, delta }: { label: string; value: string; delta: string }) {
  return (
    <div className="flex items-baseline gap-2">
      <span className="text-3xl md:text-4xl font-display leading-none">{value}</span>
      <div className="flex flex-col">
        <span className="text-[10px] font-medium uppercase tracking-widest text-zinc-500">{label}</span>
        <span className="text-xs text-emerald-600 font-medium inline-flex items-center gap-0.5"><TrendingUp className="size-3" strokeWidth={2} />{delta}</span>
      </div>
    </div>
  );
}

function ScheduleBar() {
  return (
    <div className="min-w-0 flex items-center bg-zinc-900 text-white rounded-full pr-1 pl-5 py-1 gap-3 shadow-sm">
      <span className="text-xs font-medium whitespace-nowrap hidden sm:block">AssetMap Secure</span>
      <span className="hidden md:flex items-center gap-1.5 bg-zinc-800 rounded-full px-3 py-1">
        <Shield className="size-3.5" strokeWidth={1.75} />
        <span className="text-xs whitespace-nowrap">Encrypted</span>
      </span>
      <span className="flex items-center gap-2 bg-lime-300 text-zinc-900 rounded-full px-3 py-1.5">
        <span className="text-xs font-semibold whitespace-nowrap hidden sm:block">Account Aggregator</span>
        <div className="size-4 rounded-full bg-zinc-900 grid place-items-center"><Plus className="size-3 text-white" /></div>
      </span>
    </div>
  );
}

function FilterChip({ children, active, onClick }: { children: React.ReactNode; active?: boolean; onClick?: () => void }) {
  return (
    <button onClick={onClick} className={"shrink-0 inline-flex items-center gap-1.5 rounded-full px-3 py-1.5 text-xs font-medium whitespace-nowrap transition active:scale-95 " + (active ? "bg-zinc-900 text-white shadow-sm" : "bg-white text-zinc-600 hover:text-zinc-900 hover:bg-zinc-50 border border-zinc-200")}>
      {children}
    </button>
  );
}

function DensityToggle({ density, onChange }: { density: Density; onChange: (d: Density) => void }) {
  return (
    <div className="flex items-center bg-white rounded-full p-0.5 shadow-sm border border-zinc-200">
      <button onClick={() => onChange("comfortable")} className={"inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium transition " + (density === "comfortable" ? "bg-zinc-900 text-white" : "text-zinc-500 hover:text-zinc-900")}>
        <Grid3x3 className="size-3.5" strokeWidth={2} />
      </button>
      <button onClick={() => onChange("compact")} className={"inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-medium transition " + (density === "compact" ? "bg-zinc-900 text-white" : "text-zinc-500 hover:text-zinc-900")}>
        <Grid2x2 className="size-3.5" strokeWidth={2} />
      </button>
    </div>
  );
}

function SectionHeader({ title, count, label, density }: { title: string; count: string; label: string; density?: Density }) {
  return (
    <div className={\`flex items-baseline gap-3 \${density === "compact" ? "mb-2 mt-4" : "mb-4 mt-8"}\`}>
      <h2 className="text-xl md:text-2xl font-display font-bold">{title}</h2>
      <span className="text-sm text-zinc-500"><span className="text-zinc-900 font-medium">{count}</span>{" "}<span className="underline underline-offset-4 decoration-zinc-300">{label}</span></span>
    </div>
  );
}

function AllocationPie({ segments, className = "" }: { segments: any[]; className?: string }) {
  const total = segments.reduce((s, x) => s + x.value, 0);
  const [active, setActive] = useState<string | null>(segments[0]?.key ?? null);
  const size = 260;
  const stroke = 34;
  const r = (size - stroke) / 2;
  const c = 2 * Math.PI * r;
  let offset = 0;
  const arcs = segments.map((seg) => {
    const frac = seg.value / total;
    const len = frac * c;
    const arc = { ...seg, frac, dash: \`\${len} \${c - len}\`, dashOffset: -offset };
    offset += len;
    return arc;
  });
  const activeSeg = arcs.find((a) => a.key === active) ?? arcs[0];
  const fmt = (n: number) => {
    if (n >= 10000000) return \`₹\${(n / 10000000).toFixed(2)}Cr\`;
    if (n >= 100000) return \`₹\${(n / 100000).toFixed(2)}L\`;
    return \`₹\${(n / 1000).toFixed(1)}k\`;
  };

  return (
    <section className={\`grid grid-cols-1 lg:grid-cols-[auto_1fr] gap-6 bg-white rounded-3xl p-6 shadow-sm border border-zinc-100 \${className}\`}>
      <div className="relative grid place-items-center" style={{ width: size, height: size }}>
        <svg width={size} height={size} className="-rotate-90">
          <circle cx={size / 2} cy={size / 2} r={r} fill="none" stroke="#f4f4f5" strokeWidth={stroke} />
          {arcs.map((a) => {
            const isActive = a.key === activeSeg.key;
            return (
              <circle key={a.key} cx={size / 2} cy={size / 2} r={r} fill="none" stroke={a.color} strokeWidth={isActive ? stroke + 6 : stroke} strokeDasharray={a.dash} strokeDashoffset={a.dashOffset} strokeLinecap="butt" className="cursor-pointer transition-all duration-500 ease-out" style={{ opacity: active && !isActive ? 0.35 : 1 }} onMouseEnter={() => setActive(a.key)} />
            );
          })}
        </svg>
        <div className="absolute inset-0 grid place-items-center text-center pointer-events-none">
          <div>
            <p className="text-[10px] uppercase tracking-[0.2em] text-zinc-500">{activeSeg.label}</p>
            <p className="font-display text-3xl leading-none mt-1 font-bold">{fmt(activeSeg.value)}</p>
            <p className="text-xs text-zinc-500 mt-1">{(activeSeg.frac * 100).toFixed(1)}%</p>
          </div>
        </div>
      </div>
      <div className="flex flex-col justify-center gap-2 min-w-0">
        <div className="flex items-baseline justify-between mb-1">
          <h2 className="font-display text-xl font-bold">Allocation</h2>
          <span className="text-[10px] uppercase tracking-widest text-zinc-500">Total {fmt(total)}</span>
        </div>
        {arcs.map((a) => {
          const isActive = a.key === activeSeg.key;
          return (
            <button key={a.key} onMouseEnter={() => setActive(a.key)} onClick={() => setActive(a.key)} className={\`group flex items-center gap-3 rounded-xl px-3 py-2 text-left transition \${isActive ? "bg-zinc-100" : "hover:bg-zinc-50"}\`}>
              <span className={\`size-2.5 rounded-full \${a.accent} shrink-0\`} style={{ backgroundColor: a.color }} />
              <span className="text-sm font-medium text-zinc-900 flex-1 truncate">{a.label}</span>
              <div className="w-28 h-1.5 rounded-full bg-zinc-200 overflow-hidden hidden sm:block">
                <div className="h-full rounded-full transition-all duration-700" style={{ width: \`\${a.frac * 100}%\`, backgroundColor: a.color }} />
              </div>
              <span className="text-xs tabular-nums text-zinc-500 w-12 text-right">{(a.frac * 100).toFixed(1)}%</span>
              <span className="text-xs font-medium tabular-nums w-16 text-right text-zinc-900">{fmt(a.value)}</span>
            </button>
          );
        })}
      </div>
    </section>
  );
}
\`;

