import { useEffect, useState, useCallback, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAssetStore } from '../store/assetStore';
import { getAssetSummary, getFinancialAssets, getLandRecords, getConsents, refreshAssets, getAuditLog } from '../services/assets';
import { logout } from '../services/auth';
import CoreServices from '../components/CoreServices';
import {
  ArrowUpRight, Search, SlidersHorizontal, Plus, RefreshCw,
  LayoutGrid, Wallet, Shield, PieChart, LineChart, Layers,
  Bell, ChevronDown, Settings, LogOut, UserRound, HelpCircle,
  TrendingUp, Building2, History, Store, Calendar, Flame, Grid2x2, Grid3x3
} from 'lucide-react';
import advisor1 from '../assets/advisor-1.jpg';
// using advisor1 as client1 fallback since it may not exist
const client1 = advisor1;

/* ═══════════════════════════════════════════════════
   AssetMap Dashboard — Lovable-inspired Design
   Backed by real API data from the AssetMap backend
   ═══════════════════════════════════════════════════ */

type FilterKey = 'all' | 'DEPOSIT' | 'INSURANCE_POLICIES' | 'MUTUAL_FUND' | 'EQUITY' | 'NPS' | 'GSTN';
type Density = "comfortable" | "compact";

const FILTER_META: Record<FilterKey, { label: string; icon: React.ReactNode }> = {
  all: { label: 'All', icon: null },
  DEPOSIT: { label: 'Bank', icon: <Wallet className="size-3" strokeWidth={2} /> },
  INSURANCE_POLICIES: { label: 'Insurance', icon: <Shield className="size-3" strokeWidth={2} /> },
  MUTUAL_FUND: { label: 'Mutual Funds', icon: <PieChart className="size-3" strokeWidth={2} /> },
  EQUITY: { label: 'Stocks', icon: <LineChart className="size-3" strokeWidth={2} /> },
  NPS: { label: 'NPS', icon: <Layers className="size-3" strokeWidth={2} /> },
  GSTN: { label: 'GSTN', icon: <Layers className="size-3" strokeWidth={2} /> },
};

const FI_ICONS: Record<string, React.ReactNode> = {
  DEPOSIT: <Wallet className="size-4" strokeWidth={1.75} />,
  EQUITY: <LineChart className="size-4" strokeWidth={1.75} />,
  MUTUAL_FUND: <PieChart className="size-4" strokeWidth={1.75} />,
  INSURANCE_POLICIES: <Shield className="size-4" strokeWidth={1.75} />,
  NPS: <Layers className="size-4" strokeWidth={1.75} />,
  GSTN: <Layers className="size-4" strokeWidth={1.75} />,
};

const FI_COLORS: Record<string, { iconBg: string; tag: string; color: string }> = {
  DEPOSIT: { iconBg: 'bg-zinc-900 text-lime-300', tag: 'Primary', color: '#0f172a' },
  EQUITY: { iconBg: 'bg-amber-100 text-amber-800', tag: 'Equity', color: '#f59e0b' },
  MUTUAL_FUND: { iconBg: 'bg-lime-100 text-lime-800', tag: 'MF', color: '#a3e635' },
  INSURANCE_POLICIES: { iconBg: 'bg-sky-100 text-sky-800', tag: 'Insurance', color: '#0ea5e9' },
  NPS: { iconBg: 'bg-teal-100 text-teal-800', tag: 'NPS', color: '#14b8a6' },
  GSTN: { iconBg: 'bg-red-100 text-red-800', tag: 'GSTN', color: '#ef4444' },
};

export default function Dashboard() {
  const navigate = useNavigate();
  const {
    user, summary, assets, landRecords,
    setSummary, setAssets, setLandRecords, setConsents,
    isLoadingAssets, setLoadingAssets,
  } = useAssetStore();

  const [activeTab, setActiveTab] = useState<'overview' | 'land' | 'audit' | 'services'>('overview');
  const [refreshing, setRefreshing] = useState(false);
  const [filter, setFilter] = useState<FilterKey>('all');
  const [query, setQuery] = useState('');
  const [density, setDensity] = useState<Density>("comfortable");

  const loadData = useCallback(async () => {
    setLoadingAssets(true);
    try {
      const [s, a, l, c] = await Promise.all([
        getAssetSummary(), getFinancialAssets(), getLandRecords(), getConsents(),
      ]);
      setSummary(s); setAssets(a); setLandRecords(l); setConsents(c);
    } catch (err) { console.error('Load failed', err); }
    finally { setLoadingAssets(false); }
  }, [setSummary, setAssets, setLandRecords, setConsents, setLoadingAssets]);

  useEffect(() => { loadData(); }, [loadData]);

  async function handleRefresh() {
    setRefreshing(true);
    try { await refreshAssets(); await loadData(); } catch { }
    finally { setRefreshing(false); }
  }

  async function handleLogout() {
    try { await logout(); } catch { }
    useAssetStore.getState().logout();
    navigate('/');
  }

  function fmt(n: number) {
    if (n >= 10000000) return `₹${(n / 10000000).toFixed(2)} Cr`;
    if (n >= 100000) return `₹${(n / 100000).toFixed(2)} L`;
    return `₹${n.toLocaleString('en-IN')}`;
  }

  const tabs = [
    { key: 'overview' as const, label: 'Overview', icon: <LayoutGrid className="size-4" strokeWidth={1.75} /> },
    { key: 'land' as const, label: `Property (${landRecords.length})`, icon: <Building2 className="size-4" strokeWidth={1.75} /> },
    { key: 'audit' as const, label: 'Activity', icon: <History className="size-4" strokeWidth={1.75} /> },
    { key: 'services' as const, label: 'Services', icon: <Store className="size-4" strokeWidth={1.75} /> },
  ];

  const q = query.trim().toLowerCase();
  const matchText = (text: string) => !q || text.toLowerCase().includes(q);
  const showType = (key: FilterKey) => filter === 'all' || filter === key;

  const filteredAssets = assets.filter(a =>
    showType(a.fiType as FilterKey) && matchText(`${a.institutionName} ${a.accountRef} ${a.fiType}`)
  );

  const grouped: Record<string, typeof assets> = {};
  for (const a of filteredAssets) {
    (grouped[a.fiType] ||= []).push(a);
  }

  return (
    <div className="min-h-screen bg-zinc-50/50 text-zinc-900 font-sans">
      <div className="flex">
        {/* ════════ LEFT ICON RAIL ════════ */}
        <aside className="hidden md:flex w-20 shrink-0 flex-col items-center py-8 gap-8 border-r border-zinc-200 bg-white shadow-[2px_0_15px_-3px_rgba(0,0,0,0.05)] z-10">
          <div className="size-10 rounded-full bg-zinc-900 grid place-items-center">
            <span className="text-lime-300 font-display text-xl leading-none font-bold">A</span>
          </div>
          <nav className="flex flex-col gap-3 mt-4">
            {tabs.map(t => (
              <RailIcon key={t.key} active={activeTab === t.key} label={t.label} onClick={() => setActiveTab(t.key)}>
                {t.icon}
              </RailIcon>
            ))}
          </nav>
        </aside>

        {/* ════════ MAIN ════════ */}
        <main className="flex-1 min-w-0 px-6 md:px-10 py-8 md:py-10">
          {/* Top bar */}
          <div className="flex flex-wrap items-center justify-between gap-4 mb-10">
            <div className="flex min-w-0 items-center gap-3">
              <ScheduleBar />
            </div>

            <div className="flex items-center gap-3 shrink-0">
              <div className="hidden md:flex items-center gap-4 mr-2">
                <Kpi label="Net Worth" value={fmt(summary?.totalNetWorth || 0)} delta="+Active" />
                <div className="h-10 w-px bg-zinc-300/70" />
                <Kpi label="Accounts" value={String(assets.length)} delta="+Linked" />
              </div>
              <button
                aria-label="Notifications"
                className="relative size-10 rounded-full bg-white grid place-items-center shadow-sm hover:bg-zinc-100 active:scale-95 transition border border-zinc-200"
              >
                <Bell className="size-4 text-zinc-600" strokeWidth={1.75} />
                <span className="absolute top-2 right-2 size-2 rounded-full bg-rose-500 ring-2 ring-white" />
              </button>
              <ProfileMenu user={user} onLogout={handleLogout} />
            </div>
          </div>

          {/* Display heading */}
          <div className="grid grid-cols-[minmax(0,1fr)_auto] items-center gap-4 mb-6">
            <h1 className="font-display text-[10vw] sm:text-[6vw] lg:text-[5rem] leading-[0.9] tracking-tight text-zinc-900 truncate">
              WEALTH
            </h1>
            <button onClick={handleRefresh} disabled={refreshing || isLoadingAssets} className="shrink-0 flex items-center gap-2 rounded-full bg-zinc-900 text-white pl-2 pr-5 py-2 text-sm font-medium hover:bg-zinc-800 active:scale-95 transition disabled:opacity-50">
              <span className="size-7 rounded-full bg-lime-300 text-zinc-900 grid place-items-center">
                <RefreshCw className={`size-4 ${refreshing ? 'animate-spin' : ''}`} strokeWidth={2.5} />
              </span>
              Sync Assets
            </button>
          </div>

          {/* Tab content */}
          {activeTab === 'overview' && (
            <>
              {/* Allocation Pie */}
              {!isLoadingAssets && summary && summary.categoryBreakdown.length > 0 && (
                <AllocationPie 
                  className="mb-8" 
                  segments={summary.categoryBreakdown.map(cat => ({
                    key: cat.fiType,
                    label: FILTER_META[cat.fiType as FilterKey]?.label || cat.fiType,
                    value: cat.totalValue,
                    color: FI_COLORS[cat.fiType]?.color || '#0f172a',
                    accent: FI_COLORS[cat.fiType]?.iconBg.split(' ')[0] || 'bg-slate-900'
                  }))} 
                />
              )}

              {/* Search + Category filters */}
              <div className="flex flex-col sm:flex-row sm:items-center gap-3 mb-8">
                <div className="flex items-center gap-2 bg-white rounded-full pl-3 pr-2 py-1.5 shadow-sm border border-zinc-200 w-full sm:w-72">
                  <Search className="size-3.5 text-zinc-500" strokeWidth={1.75} />
                  <input
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    placeholder="Search assets..."
                    className="flex-1 bg-transparent outline-none text-sm placeholder:text-zinc-400"
                  />
                  {query && (
                    <button onClick={() => setQuery('')} className="text-[10px] text-zinc-500 hover:text-zinc-900 px-2 py-1 rounded-full hover:bg-zinc-100">
                      Clear
                    </button>
                  )}
                </div>

                <div className="flex items-center gap-2 overflow-x-auto scrollbar-hide pb-1">
                  <button className="shrink-0 size-9 rounded-full bg-white grid place-items-center shadow-sm border border-zinc-200 hover:bg-zinc-100 transition">
                    <SlidersHorizontal className="size-3.5" strokeWidth={1.75} />
                  </button>
                  {(Object.keys(FILTER_META) as FilterKey[]).map(key => (
                    <FilterChip key={key} active={filter === key} onClick={() => setFilter(key)}>
                      {FILTER_META[key].icon}{FILTER_META[key].label}
                    </FilterChip>
                  ))}
                  <div className="w-px h-6 bg-zinc-300/70 mx-1" />
                  <DensityToggle density={density} onChange={setDensity} />
                </div>
              </div>

              {/* Loading */}
              {isLoadingAssets && (
                <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4 mb-10">
                  {[1, 2, 3].map(i => (
                    <div key={i} className="bg-white rounded-2xl p-6 shadow-sm animate-pulse border border-zinc-100">
                      <div className="flex items-start justify-between mb-4"><div className="size-10 rounded-xl bg-zinc-100" /><div className="h-4 w-16 bg-zinc-100 rounded-full" /></div>
                      <div className="h-3 w-24 bg-zinc-100 rounded mb-2" /><div className="h-4 w-32 bg-zinc-100 rounded mb-4" /><div className="h-7 w-28 bg-zinc-100 rounded" />
                    </div>
                  ))}
                </div>
              )}

              {/* Asset sections by category */}
              {!isLoadingAssets && Object.entries(grouped).map(([fiType, items]) => (
                <div key={fiType}>
                  <SectionHeader title={FILTER_META[fiType as FilterKey]?.label || fiType.replace('_', ' ')} count={String(items.length)} label="Accounts" density={density} />
                  <div className={`grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 ${density === 'compact' ? 'gap-3 mb-6' : 'gap-5 mb-10'}`}>
                    {items.map(asset => <AssetCard key={asset.id} asset={asset} fmt={fmt} density={density} />)}
                  </div>
                </div>
              ))}

              {/* Empty state */}
              {!isLoadingAssets && filteredAssets.length === 0 && (
                <div className="bg-white rounded-2xl p-10 text-center shadow-sm border border-zinc-100">
                  <p className="text-sm text-zinc-500">{query || filter !== 'all' ? 'No assets match your search.' : 'No financial assets found.'}</p>
                </div>
              )}
            </>
          )}

          {activeTab === 'land' && (
            <div><h2 className="text-2xl font-display mb-4">Property & Land</h2>{/* render land records */}</div>
          )}
          {activeTab === 'audit' && (
            <div><h2 className="text-2xl font-display mb-4">Activity Log</h2>{/* render audit */}</div>
          )}
          {activeTab === 'services' && (
            <div><h2 className="text-2xl font-display mb-4">Services</h2><CoreServices /></div>
          )}
        </main>
      </div>
    </div>
  );
}

/* ═══════════════════════════════════════════════════
   UI COMPONENTS
   ═══════════════════════════════════════════════════ */

function AssetCard({ asset, fmt, density }: { asset: any; fmt: (n: number) => string; density: Density }) {
  if (asset.fiType === 'DEPOSIT') {
    const last4 = asset.accountRef ? asset.accountRef.slice(-4) : '0000';
    return (
      <article className="bg-zinc-50/30 rounded-3xl p-1 shadow-sm border border-zinc-100 hover:shadow-md transition group">
        <div className="relative w-full aspect-[1.586/1] rounded-[24px] bg-gradient-to-br from-zinc-800 via-zinc-900 to-black p-5 flex flex-col justify-between text-white shadow-xl overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-tr from-white/10 to-transparent opacity-30 pointer-events-none mix-blend-overlay"></div>
          <div className="relative z-10 flex justify-between items-start">
            <div>
              <p className="text-[9px] tracking-[0.25em] text-zinc-400 font-medium uppercase mb-1">DEBIT</p>
              <h3 className="font-semibold text-lg leading-tight tracking-wide">{asset.institutionName}</h3>
            </div>
            <span className="text-[10px] font-medium bg-white/10 border border-white/5 text-white rounded-full px-3 py-1 backdrop-blur-md shadow-sm">
              Primary
            </span>
          </div>
          <div className="relative z-10 flex items-center gap-3 mt-4">
            <div className="w-10 h-7 bg-gradient-to-br from-[#d4af37] via-[#f3e5ab] to-[#aa7c11] rounded-[4px] p-0.5 shadow-sm border border-[#8c6b12] flex flex-col justify-between relative overflow-hidden">
              <div className="w-full h-[1px] bg-[#8c6b12]/50 absolute top-2 left-0"></div>
              <div className="w-full h-[1px] bg-[#8c6b12]/50 absolute bottom-2 left-0"></div>
              <div className="w-[1px] h-full bg-[#8c6b12]/50 absolute left-2.5 top-0"></div>
              <div className="w-[1px] h-full bg-[#8c6b12]/50 absolute right-2.5 top-0"></div>
              <div className="w-3 h-full bg-[#8c6b12]/20 absolute left-1/2 -translate-x-1/2 top-0 border-x border-[#8c6b12]/40"></div>
            </div>
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" className="text-[#98cc3b] rotate-90 ml-1">
              <path d="M5 12a10 10 0 0 1 14 0" />
              <path d="M8 12a6 6 0 0 1 8 0" />
              <path d="M11 12a2 2 0 0 1 2 0" />
            </svg>
          </div>
          <div className="relative z-10 flex items-center gap-4 mt-5 text-white">
            <span className="text-[14px] leading-none tracking-[0.2em] mb-1">••••</span>
            <span className="text-[14px] leading-none tracking-[0.2em] mb-1">••••</span>
            <span className="text-[14px] leading-none tracking-[0.2em] mb-1">••••</span>
            <span className="font-mono text-[17px] tracking-[0.15em] leading-none">{last4}</span>
          </div>
          <div className="relative z-10 flex justify-between items-end mt-4">
            <div className="flex gap-10">
              <div>
                <p className="text-[7px] tracking-widest text-zinc-400 uppercase mb-0.5">Cardholder</p>
                <p className="text-[11px] font-semibold tracking-widest uppercase text-white/90">ASSETMAP USER</p>
              </div>
              <div>
                <p className="text-[7px] tracking-widest text-zinc-400 uppercase mb-0.5">Exp</p>
                <p className="text-[11px] font-bold tracking-wider text-white/90">08/29</p>
              </div>
            </div>
            <div className="text-2xl font-bold italic pr-1 tracking-tighter text-white/90 select-none">VISA</div>
          </div>
        </div>
        <div className="px-3 pt-3 pb-2 flex justify-between items-end">
           <div>
             <p className="text-xs text-zinc-500 mb-0.5">Checking <span className="tracking-widest ml-1">••{last4}</span></p>
             <p className="text-[22px] font-display font-semibold text-zinc-800">{fmt(asset.balance)}</p>
           </div>
           <div className="text-right">
             <div className="flex justify-end gap-0.5 mb-1">
                <span className="size-[6px] rounded-full bg-cyan-400" />
                <span className="size-[6px] rounded-full bg-emerald-400" />
                <span className="size-[6px] rounded-full bg-amber-400" />
             </div>
             <p className="text-[11px] text-emerald-600 font-medium">Active</p>
           </div>
        </div>
      </article>
    );
  }

  if (asset.fiType === 'INSURANCE_POLICIES') {
    return <InsuranceCard policy={asset} fmt={fmt} density={density} />;
  }

  if (asset.fiType === 'MUTUAL_FUND') {
    return <MutualFundCard fund={asset} fmt={fmt} density={density} />;
  }

  if (asset.fiType === 'EQUITY') {
    return <StockCard stock={asset} fmt={fmt} density={density} />;
  }

  // Fallback
  const colors = FI_COLORS[asset.fiType] || FI_COLORS.DEPOSIT;
  const icon = FI_ICONS[asset.fiType] || <Wallet className="size-4" strokeWidth={1.75} />;
  return (
    <article className="bg-white rounded-2xl p-4 shadow-sm hover:shadow-md transition border border-zinc-100">
      <div className="flex items-start justify-between mb-4">
        <div className={`size-10 rounded-xl ${colors.iconBg} grid place-items-center`}>{icon}</div>
        <span className="text-[10px] font-medium bg-zinc-100 text-zinc-600 rounded-full px-2 py-0.5">{colors.tag}</span>
      </div>
      <p className="text-xs text-zinc-500 mb-1 font-mono">{asset.accountRef}</p>
      <h3 className="text-base font-display font-semibold leading-tight">{asset.institutionName}</h3>
      <p className="mt-3 text-2xl font-display font-bold">{fmt(asset.balance)}</p>
    </article>
  );
}

function InsuranceCard({ policy, fmt, density }: { policy: any; fmt: (n:number)=>string; density: Density }) {
  const cardPad = density === "compact" ? "p-3" : "p-4";
  return (
    <article className={`bg-white rounded-2xl ${cardPad} shadow-sm border border-zinc-100 hover:shadow-md transition flex flex-col`}>
      <div className="flex items-start justify-between mb-3">
        <div className="size-10 rounded-xl bg-zinc-100 grid place-items-center">
          <Shield className="size-4 text-zinc-700" strokeWidth={1.75} />
        </div>
        <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-sky-100 text-sky-700">
          Active
        </span>
      </div>
      <h3 className="text-sm font-display leading-tight">{policy.institutionName}</h3>
      <p className="text-xs text-zinc-500 mt-1">{policy.accountRef}</p>
      <div className="mt-auto pt-4 flex items-baseline justify-between">
        <span className="text-[10px] font-medium uppercase tracking-widest text-zinc-400">Sum Assured</span>
        <span className="text-sm font-semibold text-zinc-900">{fmt(policy.balance)}</span>
      </div>
    </article>
  );
}

function MutualFundCard({ fund, fmt, density }: { fund: any; fmt: (n:number)=>string; density: Density }) {
  const cardPad = density === "compact" ? "p-3" : "p-4";
  return (
    <article className={`bg-white rounded-2xl ${cardPad} shadow-sm border border-zinc-100 hover:shadow-md transition`}>
      <div className="flex items-start justify-between mb-3">
        <div className="size-10 rounded-xl bg-lime-100 text-lime-800 grid place-items-center">
          <PieChart className="size-4" strokeWidth={1.75} />
        </div>
        <button className="size-7 rounded-full bg-zinc-100 grid place-items-center text-zinc-500 hover:bg-zinc-900 hover:text-white transition">
          <ArrowUpRight className="size-3.5" strokeWidth={2} />
        </button>
      </div>
      <h3 className="text-base font-display leading-tight line-clamp-1">{fund.institutionName}</h3>
      <p className="text-xs text-zinc-500 mt-1">{fund.accountRef}</p>

      <div className="mt-4 flex items-baseline gap-2">
        <span className="text-xl font-display">{fmt(fund.balance)}</span>
        <span className="text-xs font-medium text-emerald-600">+4.2%</span>
      </div>
    </article>
  );
}

function StockCard({ stock, fmt, density }: { stock: any; fmt: (n:number)=>string; density: Density }) {
  const cardPad = density === "compact" ? "p-3" : "p-4";
  return (
    <article className={`bg-white rounded-2xl ${cardPad} shadow-sm border border-zinc-100 hover:shadow-md transition`}>
      <div className="flex items-start justify-between mb-3">
        <div>
          <h3 className="text-base font-display leading-none">{stock.institutionName}</h3>
          <p className="text-xs text-zinc-500 mt-1">{stock.accountRef}</p>
        </div>
        <span className="inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-semibold bg-lime-300 text-zinc-900">
          +1.8%
        </span>
      </div>
      <p className="text-xl font-display">{fmt(stock.balance)}</p>
      <div className="mt-2 h-10 bg-zinc-50 rounded animate-pulse"></div>
    </article>
  );
}


function ProfileMenu({ user, onLogout }: { user: any; onLogout: () => void }) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const onClick = (e: MouseEvent) => { if (!ref.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("mousedown", onClick);
    return () => document.removeEventListener("mousedown", onClick);
  }, []);

  return (
    <div ref={ref} className="relative z-50">
      <button onClick={() => setOpen((v) => !v)} className="flex items-center gap-2 bg-white rounded-full pl-1 pr-3 py-1 shadow-sm border border-zinc-200 hover:bg-zinc-100 active:scale-[0.98] transition">
        <div className="size-8 rounded-full bg-lime-300 text-zinc-900 font-bold grid place-items-center">
           {user?.name?.[0] || 'U'}
        </div>
        <span className="hidden sm:flex flex-col items-start leading-tight">
          <span className="text-xs font-semibold">{user?.name || 'User'}</span>
          <span className="text-[10px] text-zinc-500">{user?.mobile || 'Client'}</span>
        </span>
        <ChevronDown className={"size-3.5 text-zinc-500 transition " + (open ? "rotate-180" : "")} strokeWidth={2} />
      </button>

      {open && (
        <div className="absolute right-0 mt-2 w-60 bg-white rounded-2xl shadow-lg ring-1 ring-black/5 py-2 z-50 origin-top-right">
          <div className="px-4 py-3 border-b border-zinc-100">
            <p className="text-sm font-semibold">{user?.name}</p>
            <p className="text-xs text-zinc-500">{user?.mobile}</p>
          </div>
          <button className="w-full flex items-center gap-3 px-4 py-2 text-sm text-left hover:bg-zinc-50 transition text-zinc-800"><Settings className="size-4 text-zinc-500" /> Account Settings</button>
          <div className="my-1 border-t border-zinc-100" />
          <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-2 text-sm text-left hover:bg-zinc-50 transition text-rose-600"><LogOut className="size-4 text-rose-500" /> Sign out</button>
        </div>
      )}
    </div>
  );
}

function RailIcon({ children, active, label, onClick }: { children: React.ReactNode; active?: boolean; label?: string; onClick?: ()=>void }) {
  return (
    <button onClick={onClick} title={label} className={"size-10 rounded-full grid place-items-center transition active:scale-95 " + (active ? "bg-zinc-900 text-white shadow-md" : "bg-white/60 text-zinc-500 hover:bg-white hover:text-zinc-900 hover:shadow-sm")}>
      {children}
    </button>
  );
}

function Kpi({ label, value, delta }: { label: string; value: string; delta: string }) {
  return (
    <div className="flex items-baseline gap-2">
      <span className="text-3xl md:text-4xl font-display leading-none">{value}</span>
      <div className="flex flex-col">
        <span className="text-[10px] font-medium uppercase tracking-widest text-zinc-500">{label}</span>
        <span className="text-xs text-emerald-600 font-medium inline-flex items-center gap-0.5"><TrendingUp className="size-3" strokeWidth={2} />{delta}</span>
      </div>
