import { useParams, useNavigate } from 'react-router-dom';
import { useAssetStore } from '../store/assetStore';
import AssetTimeline from '../components/AssetTimeline';
import { ArrowLeft, Wallet, TrendingUp, Landmark, Shield, FileText, Calendar, Lock, Globe, CheckCircle2, Building2 } from 'lucide-react';

export default function AssetDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const assets = useAssetStore((s) => s.assets);

  const asset = assets.find((a) => a.id === id);

  const FI_COLORS: Record<string, string> = {
    DEPOSIT: '#10b981', EQUITY: '#3b82f6', MUTUAL_FUND: '#8b5cf6',
    INSURANCE_POLICIES: '#f59e0b', NPS: '#14b8a6', GSTN: '#ef4444',
  };

  const FI_LABELS: Record<string, string> = {
    DEPOSIT: 'Bank Deposit', EQUITY: 'Equity', MUTUAL_FUND: 'Mutual Fund',
    INSURANCE_POLICIES: 'Insurance Policy', NPS: 'National Pension', GSTN: 'GST Record',
  };

  const FI_ICONS: Record<string, React.ReactNode> = {
    DEPOSIT: <Wallet className="size-6 text-emerald-600" strokeWidth={1.75} />,
    EQUITY: <TrendingUp className="size-6 text-blue-600" strokeWidth={1.75} />,
    MUTUAL_FUND: <Building2 className="size-6 text-purple-600" strokeWidth={1.75} />,
    INSURANCE_POLICIES: <Shield className="size-6 text-amber-600" strokeWidth={1.75} />,
    NPS: <Landmark className="size-6 text-teal-600" strokeWidth={1.75} />,
    GSTN: <FileText className="size-6 text-red-600" strokeWidth={1.75} />,
  };

  if (!asset) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-zinc-50">
        <div className="bg-white rounded-3xl p-10 text-center shadow-sm ring-1 ring-zinc-100 max-w-sm">
          <div className="size-16 bg-zinc-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <FileText className="size-8 text-zinc-400" />
          </div>
          <h2 className="text-xl font-semibold text-zinc-900 mb-2">Asset not found</h2>
          <p className="text-sm text-zinc-500 mb-8">This account could not be located in your portfolio.</p>
          <button onClick={() => navigate('/dashboard')} className="w-full py-3 bg-zinc-900 text-white rounded-xl font-medium hover:bg-black transition-colors">
            Return to Dashboard
          </button>
        </div>
      </div>
    );
  }

  const color = FI_COLORS[asset.fiType] || '#6366f1';
  const icon = FI_ICONS[asset.fiType] || <Wallet className="size-6 text-zinc-600" strokeWidth={1.75} />;

  return (
    <div className="min-h-screen bg-[#fafafa] pb-24 font-sans text-zinc-900 selection:bg-lime-200">
      {/* Navbar / Header Area */}
      <nav className="sticky top-0 z-40 bg-white/80 backdrop-blur-xl border-b border-zinc-200/50 px-6 py-4 mb-8">
        <div className="max-w-5xl mx-auto flex items-center gap-4">
          <button onClick={() => navigate('/dashboard')} className="flex items-center justify-center size-10 rounded-full bg-zinc-100 text-zinc-600 hover:bg-zinc-200 hover:text-zinc-900 transition-colors">
            <ArrowLeft className="size-5" />
          </button>
          <span className="font-medium text-zinc-600">Back to Dashboard</span>
        </div>
      </nav>

      <div className="max-w-5xl mx-auto px-6 space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">

        {/* Asset Header Card */}
        <div className="bg-white rounded-[32px] p-8 md:p-10 shadow-sm ring-1 ring-zinc-200/50 flex flex-col md:flex-row md:items-center gap-8 justify-between relative overflow-hidden">
          {/* Subtle colored glow in corner */}
          <div className="absolute -top-24 -right-24 w-64 h-64 rounded-full blur-[80px] pointer-events-none opacity-20" style={{ backgroundColor: color }}></div>

          <div className="flex items-center gap-6 relative z-10">
            <div className="size-20 rounded-[20px] flex items-center justify-center shadow-sm" style={{ backgroundColor: `${color}15`, color }}>
              {icon}
            </div>
            <div>
              <h1 className="text-3xl font-display font-semibold text-zinc-900 tracking-tight mb-2">{asset.institutionName}</h1>
              <div className="flex flex-wrap items-center gap-3">
                <span className="text-[11px] font-medium uppercase tracking-widest px-3 py-1 rounded-full" style={{ backgroundColor: `${color}15`, color }}>
                  {FI_LABELS[asset.fiType] || asset.fiType}
                </span>
                <span className="text-sm font-medium text-zinc-500 bg-zinc-100 px-3 py-1 rounded-full border border-zinc-200/60">
                  Ref: <span className="text-zinc-900 font-mono tracking-wider">{asset.accountRef}</span>
                </span>
              </div>
            </div>
          </div>

          <div className="md:text-right relative z-10 bg-zinc-50 md:bg-transparent rounded-2xl p-6 md:p-0 border border-zinc-100 md:border-none">
            <p className="text-sm font-medium text-zinc-500 mb-1 uppercase tracking-wider">Current Value</p>
            <p className="text-[40px] font-display font-bold tracking-tight" style={{ color }}>
              ₹{asset.balance.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
            </p>
          </div>
        </div>

        {/* Value Timeline */}
        <div className="bg-white rounded-[32px] p-8 shadow-sm ring-1 ring-zinc-200/50">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-xl font-semibold tracking-tight text-zinc-800">Value History</h3>
            <span className="text-xs font-medium text-zinc-400 uppercase tracking-widest bg-zinc-50 px-3 py-1 rounded-full border border-zinc-100">Simulated</span>
          </div>
          <div className="-mx-2">
            <AssetTimeline color={color} currentValue={asset.balance} />
          </div>
        </div>

        {/* Details Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-white rounded-[32px] p-8 shadow-sm ring-1 ring-zinc-200/50">
            <div className="flex items-center gap-3 mb-8">
              <div className="size-10 rounded-full bg-blue-50 flex items-center justify-center">
                <FileText className="size-5 text-blue-600" />
              </div>
              <h3 className="text-lg font-semibold text-zinc-800">Account Details</h3>
            </div>

            <div className="space-y-1">
              <DetailRow label="Institution" value={asset.institutionName} />
              <DetailRow label="Account Reference" value={asset.accountRef} isCode />
              <DetailRow label="Asset Type" value={FI_LABELS[asset.fiType] || asset.fiType} />
              <DetailRow label="Currency" value={asset.currency} />
              <DetailRow label="Last Fetched" value={new Date(asset.fetchedAt).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })} icon={<Calendar className="size-3.5 mr-1 text-zinc-400" />} />
            </div>
          </div>

          <div className="bg-white rounded-[32px] p-8 shadow-sm ring-1 ring-zinc-200/50">
            <div className="flex items-center gap-3 mb-8">
              <div className="size-10 rounded-full bg-emerald-50 flex items-center justify-center">
                <Shield className="size-5 text-emerald-600" />
              </div>
              <h3 className="text-lg font-semibold text-zinc-800">Security & Source</h3>
            </div>

            <div className="space-y-1">
              <DetailRow label="Data Source" value="Account Aggregator (Setu)" icon={<Globe className="size-3.5 mr-1 text-zinc-400" />} />
              <DetailRow label="Framework" value="ReBIT AA Standard v2.0" />
              <DetailRow label="Encryption" value="AES-256-GCM" icon={<Lock className="size-3.5 mr-1 text-zinc-400" />} />
              <DetailRow label="Consent Status" value="Active & Verified" valueColor="#10b981" icon={<CheckCircle2 className="size-3.5 mr-1 text-emerald-500" />} />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

function DetailRow({ label, value, valueColor, isCode, icon }: { label: string; value: string; valueColor?: string; isCode?: boolean; icon?: React.ReactNode }) {
  return (
    <div className="flex flex-col sm:flex-row sm:items-center justify-between py-3 border-b border-zinc-100 last:border-0 gap-2 sm:gap-0">
      <span className="text-sm font-medium text-zinc-500">{label}</span>
      <span className={`text-sm flex items-center ${isCode ? 'font-mono bg-zinc-100 px-2 py-0.5 rounded-md text-zinc-700 tracking-wide' : 'font-semibold text-zinc-800'}`} style={valueColor ? { color: valueColor } : undefined}>
        {icon}
        {value}
      </span>
    </div>
  );
}

